"""Current implementation prose for the Word technical panorama.

Narrative is maintained here; ABI, settings, material bindings and source
identities are read by the builder from the corresponding live source files.
"""
def P(text): return {"kind": "p", "text": text}
def H(text): return {"kind": "h2", "text": text}
def T(headers, rows, widths=None): return {"kind": "table", "headers": headers, "rows": rows, "widths": widths}
def F(key, caption): return {"kind": "figure", "key": key, "caption": caption}
def S(title, sources, *blocks): return {"title": title, "sources": sources, "blocks": list(blocks)}

